mapper.select:
SELECT MAX(a.id) AS process_id, MAX(a.task_code) AS task_code, MAX(a.task_name) AS task_name, MAX(b.ID) AS thread_id, MAX(b.task_thread_desc) AS task_thread_desc, MAX(f.ID) AS system_id, MAX(f.system_code) AS system_code, MAX(f.system_desc) AS system_desc, MAX(d.platform_id) AS platform_id, MAX(e.platfrom_code) AS platfrom_code, h.ID AS api_id, MAX(c.index_id) AS index_id, MAX(h.api_contract) AS api_contract, MAX(h.api_type) AS "httpMethod", MAX(h.api_method) AS api_method, MAX(h.api_wildcard) AS api_wildcard, MAX(h.api_index_code) AS api_index_code, MAX(h.api_resource_code) AS api_resource_code, MAX(h.api_time_start) AS api_time_start, MAX(h.api_time_end) AS api_time_end, MAX(h.api_time_unit) AS api_time_unit, MAX(k.resource_id) AS resource_id, MAX(l.ip_address) AS resource_ip, string_agg(DISTINCT '"' || i.api_head_code || '":"' || i.api_head_content || '"', ',') AS headers, string_agg( DISTINCT '"' || j.api_params_code || CASE WHEN j.api_params_value_type = '4' THEN '":' || j.api_params_value ELSE '":"' || j.api_params_value || '"' END, ',' ) AS paramaters FROM system_docking.api_task_ins a LEFT JOIN system_docking.api_task_thread_ins b ON a.id = b.task_id LEFT JOIN system_docking.api_task_thread_index c ON b.id = c.thread_id LEFT JOIN system_docking.api_platform_index_info d ON c.index_id = d.id LEFT JOIN system_docking.api_interface_system_platform_info e ON d.platform_id = e.id LEFT JOIN system_docking.api_interface_system_info f ON e.system_id = f.id LEFT JOIN system_docking.api_system_api_index o ON d.id = o.index_id LEFT JOIN system_docking.api_system_api_info h ON o.api_id = h.id LEFT JOIN system_docking.api_system_api_head_info i ON h.ID = i.api_id AND i.api_head_type = '1' LEFT JOIN system_docking.api_system_api_params j ON h.ID = j.api_id LEFT JOIN system_docking.api_system_api_resource k ON h.ID = k.api_id LEFT JOIN system_docking.api_system_resource_ip l ON k.resource_id = l.resource_id LEFT JOIN system_docking.api_system_resource m ON m.ID = k.resource_id AND m.is_enable = '1' WHERE a.is_enable = '1' AND b.is_enable = '1' AND d.is_enable = '1' AND e.is_enable = '1' AND f.is_enable = '1' AND h.is_enable = '1' AND ( h.ID IS NOT NULL OR h.ID <> '' )
AND a.id=#{processId}
GROUP BY h.ID ORDER BY h.ID

SELECT MAX(a.id) AS process_id, MAX(a.task_code) AS task_code, MAX(a.task_name) AS task_name, MAX(b.ID) AS thread_id, MAX(b.task_thread_desc) AS task_thread_desc, MAX(f.ID) AS system_id, MAX(f.system_code) AS system_code, MAX(f.system_desc) AS system_desc, MAX(d.platform_id) AS platform_id, MAX(e.platfrom_code) AS platfrom_code, h.ID AS api_id, MAX(c.index_id) AS index_id, MAX(h.api_contract) AS api_contract, MAX(h.api_type) AS "httpMethod", MAX(h.api_method) AS api_method, MAX(h.api_wildcard) AS api_wildcard, MAX(h.api_index_code) AS api_index_code, MAX(h.api_time_start) AS api_time_start, MAX(h.api_time_end) AS api_time_end, MAX(h.api_time_unit) AS api_time_unit, string_agg(DISTINCT '"' || i.api_head_code || '":"' || i.api_head_content || '"', ',') AS headers, '' AS paramaters FROM system_docking.api_task_ins a LEFT JOIN system_docking.api_task_thread_ins b ON a.id = b.task_id LEFT JOIN system_docking.api_task_thread_index c ON b.id = c.thread_id LEFT JOIN system_docking.api_platform_index_info d ON c.index_id = d.id LEFT JOIN system_docking.api_interface_system_platform_info e ON d.platform_id = e.id LEFT JOIN system_docking.api_interface_system_info f ON e.system_id = f.id LEFT JOIN system_docking.api_system_api_index o ON d.id = o.index_id LEFT JOIN system_docking.api_system_api_info h ON o.api_id = h.id LEFT JOIN system_docking.api_system_api_head_info i ON h.ID = i.api_id AND i.api_head_type = '1' WHERE a.is_enable = '1' AND b.is_enable = '1' AND d.is_enable = '1' AND e.is_enable = '1' AND f.is_enable = '1' AND h.is_enable = '1' AND ( h.ID IS NOT NULL OR h.ID <> '' )
AND a.id=#{processId}
GROUP BY h.ID ORDER BY h.ID
